36	constexpr int32_t kACT_SWIGLU{2};
37	constexpr int32_t kACT_RELU2{4};
38	constexpr int32_t kHALF_PER_VECTOR{8};
39	constexpr int32_t kSWIGLU_CHUNK_ROWS{64};
40	constexpr int32_t kSWIGLU_STORAGE_ROWS{2 * kSWIGLU_CHUNK_ROWS};
41	constexpr int32_t kTHREADS_PER_BLOCK{256};
42	constexpr int32_t kMAX_TOP_K{8};
43	constexpr int32_t kMAX_FUSED_ROUTING_TOKENS{kTHREADS_PER_BLOCK};
