50	bool isValidGemmSetup(F16MoeGemmSetup const& setup) noexcept
51	{
52	    return setup.metadata.problemShapes != nullptr && setup.metadata.strides != nullptr
53	        && setup.metadata.addresses != nullptr && setup.input != nullptr && setup.weights != nullptr
54	        && setup.output != nullptr && setup.n > 0 && setup.k > 0;
55	}
