57	__global__ void countRoutesKernel(int32_t const* topkIds, int32_t* expertCounts, int32_t routedRows, int32_t numExperts)
58	{
59	    int32_t const route = static_cast<int32_t>(blockIdx.x * blockDim.x + threadIdx.x);
60	    if (route < routedRows)
61	    {
62	        int32_t const expert = topkIds[route];
63	        if (expert >= 0 && expert < numExperts)
64	        {
65	            atomicAdd(expertCounts + expert, 1);
66	        }
67	    }
68	}
