70	__device__ void populateGemmMetadata(F16MoeGemmSetup const& setup, int32_t expert, int32_t rowOffset, int32_t rows)
71	{
72	    int32_t const shapeBase = expert * 4;
73	    setup.metadata.problemShapes[shapeBase] = rows;
74	    setup.metadata.problemShapes[shapeBase + 1] = setup.n;
75	    setup.metadata.problemShapes[shapeBase + 2] = setup.k;
76	    setup.metadata.problemShapes[shapeBase + 3] = 1;
77	
78	    int32_t const strideBase = expert * 3 * 2;
79	    setup.metadata.strides[strideBase] = setup.k;
80	    setup.metadata.strides[strideBase + 1] = 1;
81	    setup.metadata.strides[strideBase + 2] = setup.k;
82	    setup.metadata.strides[strideBase + 3] = 1;
83	    setup.metadata.strides[strideBase + 4] = setup.n;
84	    setup.metadata.strides[strideBase + 5] = 1;
85	
86	    auto const* input = static_cast<__half const*>(setup.input);
87	    auto const* weights = static_cast<__half const*>(setup.weights);
88	    auto* output = static_cast<__half*>(setup.output);
89	    int32_t const addressBase = expert * 3;
90	    setup.metadata.addresses[addressBase]
91	        = reinterpret_cast<int64_t>(input + static_cast<int64_t>(rowOffset) * setup.k);
92	    setup.metadata.addresses[addressBase + 1]
93	        = reinterpret_cast<int64_t>(weights + static_cast<int64_t>(expert) * setup.n * setup.k);
94	    setup.metadata.addresses[addressBase + 2]
95	        = reinterpret_cast<int64_t>(output + static_cast<int64_t>(rowOffset) * setup.n);
96	}
