98	template <int32_t TOP_K>
99	__global__ void fusedBuildRoutingAndGemmMetadataKernel(F16MoeRoutingBuffers buffers, F16MoeGemmSetup fc1Setup,
100	    F16MoeGemmSetup fc2Setup, int32_t const* topkIds, int32_t numTokens, int32_t numExperts)
101	{
102	    __shared__ int32_t sharedExpertCounts[kTHREADS_PER_BLOCK];
103	    __shared__ int32_t sharedExpertWriteOffsets[kTHREADS_PER_BLOCK];
104	
105	    int32_t const thread = static_cast<int32_t>(threadIdx.x);
106	    if (thread < numExperts)
107	    {
108	        sharedExpertCounts[thread] = 0;
109	    }
110	    __syncthreads();
111	
112	    int32_t const token = thread;
113	    if (token < numTokens)
114	    {
115	#pragma unroll
116	        for (int32_t slot = 0; slot < TOP_K; ++slot)
117	        {
118	            int32_t const expandedRow = token * TOP_K + slot;
119	            int32_t const expert = topkIds[expandedRow];
120	            if (expert >= 0 && expert < numExperts)
121	            {
122	                atomicAdd(sharedExpertCounts + expert, 1);
123	            }
124	        }
125	    }
126	    __syncthreads();
127	
128	    if (thread == 0)
129	    {
130	        int32_t prefix{0};
131	        buffers.expertOffsets[0] = 0;
132	        for (int32_t expert = 0; expert < numExperts; ++expert)
133	        {
134	            prefix += sharedExpertCounts[expert];
135	            buffers.expertOffsets[expert + 1] = prefix;
136	        }
137	    }
138	    __syncthreads();
139	
140	    if (thread < numExperts)
141	    {
142	        int32_t const rowOffset = buffers.expertOffsets[thread];
143	        int32_t const rows = sharedExpertCounts[thread];
144	        buffers.expertCounts[thread] = rows;
145	        sharedExpertWriteOffsets[thread] = rowOffset;
146	        populateGemmMetadata(fc1Setup, thread, rowOffset, rows);
147	        populateGemmMetadata(fc2Setup, thread, rowOffset, rows);
148	    }
149	    __syncthreads();
150	
151	    if (token < numTokens)
152	    {
153	#pragma unroll
154	        for (int32_t slot = 0; slot < TOP_K; ++slot)
155	        {
156	            int32_t const expandedRow = token * TOP_K + slot;
157	            int32_t const expert = topkIds[expandedRow];
158	            if (expert >= 0 && expert < numExperts)
159	            {
160	                int32_t const sortedRow = atomicAdd(sharedExpertWriteOffsets + expert, 1);
161	                buffers.sortedToExpanded[sortedRow] = expandedRow;
162	                buffers.expandedToSorted[expandedRow] = sortedRow;
163	            }
164	        }
165	    }
166	    __syncthreads();
167	
168	    if (thread < numExperts)
169	    {
170	        buffers.expertWriteOffsets[thread] = sharedExpertWriteOffsets[thread];
171	    }
172	}
