174	cudaError_t launchFusedBuildRoutingAndGemmMetadata(F16MoeRoutingBuffers const& buffers, F16MoeGemmSetup const& fc1Setup,
175	    F16MoeGemmSetup const& fc2Setup, int32_t const* topkIds, int32_t numTokens, int32_t topK, int32_t numExperts,
176	    cudaStream_t stream)
177	{
178	    bool launched{true};
179	    switch (topK)
180	    {
181	    case 1:
182	        fusedBuildRoutingAndGemmMetadataKernel<1>
183	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
184	        break;
185	    case 2:
186	        fusedBuildRoutingAndGemmMetadataKernel<2>
187	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
188	        break;
189	    case 3:
190	        fusedBuildRoutingAndGemmMetadataKernel<3>
191	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
192	        break;
193	    case 4:
194	        fusedBuildRoutingAndGemmMetadataKernel<4>
195	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
196	        break;
197	    case 5:
198	        fusedBuildRoutingAndGemmMetadataKernel<5>
199	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
200	        break;
201	    case 6:
202	        fusedBuildRoutingAndGemmMetadataKernel<6>
203	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
204	        break;
205	    case 7:
206	        fusedBuildRoutingAndGemmMetadataKernel<7>
207	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
208	        break;
209	    case 8:
210	        fusedBuildRoutingAndGemmMetadataKernel<8>
211	            <<<1, kTHREADS_PER_BLOCK, 0, stream>>>(buffers, fc1Setup, fc2Setup, topkIds, numTokens, numExperts);
212	        break;
213	    default: launched = false; break;
214	    }
215	    if (!launched)
216	    {
217	        return cudaErrorInvalidValue;
218	    }
219	    return cudaGetLastError();
220	}
