222	__global__ void buildOffsetsKernel(int32_t const* expertCounts, int32_t* expertOffsets, int32_t* expertWriteOffsets,
223	    F16MoeGemmSetup fc1Setup, F16MoeGemmSetup fc2Setup, int32_t numExperts)
224	{
225	    if (threadIdx.x == 0)
226	    {
227	        int32_t prefix{0};
228	        expertOffsets[0] = 0;
229	        for (int32_t expert = 0; expert < numExperts; ++expert)
230	        {
231	            prefix += expertCounts[expert];
232	            expertOffsets[expert + 1] = prefix;
233	        }
234	    }
235	    __syncthreads();
236	
237	    int32_t const expert = static_cast<int32_t>(threadIdx.x);
238	    if (expert < numExperts)
239	    {
240	        int32_t const rowOffset = expertOffsets[expert];
241	        expertWriteOffsets[expert] = rowOffset;
242	        int32_t const rows = expertCounts[expert];
243	        populateGemmMetadata(fc1Setup, expert, rowOffset, rows);
244	        populateGemmMetadata(fc2Setup, expert, rowOffset, rows);
245	    }
246	}
