248	__global__ void scatterRouteMapKernel(int32_t const* topkIds, int32_t* expertWriteOffsets, int32_t* sortedToExpanded,
249	    int32_t* expandedToSorted, int32_t routedRows, int32_t numExperts)
250	{
251	    int32_t const expandedRow = static_cast<int32_t>(blockIdx.x * blockDim.x + threadIdx.x);
252	    if (expandedRow < routedRows)
253	    {
254	        int32_t const expert = topkIds[expandedRow];
255	        if (expert >= 0 && expert < numExperts)
256	        {
257	            int32_t const sortedRow = atomicAdd(expertWriteOffsets + expert, 1);
258	            sortedToExpanded[sortedRow] = expandedRow;
259	            expandedToSorted[expandedRow] = sortedRow;
260	        }
261	    }
262	}
