264	__global__ void gatherHiddenKernel(uint4 const* hiddenStates, uint4* gatheredInput, int32_t const* sortedToExpanded,
265	    int32_t routedRows, int32_t topK, int32_t vectorsPerRow)
266	{
267	    int64_t const vector = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
268	    int64_t const numVectors = static_cast<int64_t>(routedRows) * vectorsPerRow;
269	    if (vector < numVectors)
270	    {
271	        int32_t const sortedRow = static_cast<int32_t>(vector / vectorsPerRow);
272	        int32_t const vectorInRow = static_cast<int32_t>(vector % vectorsPerRow);
273	        int32_t const expandedRow = sortedToExpanded[sortedRow];
274	        int32_t const token = expandedRow / topK;
275	        gatheredInput[vector] = hiddenStates[static_cast<int64_t>(token) * vectorsPerRow + vectorInRow];
276	    }
277	}
