279	__global__ void activateFc1Kernel(
280	    __half const* rawFc1, __half* activatedFc1, int32_t routedRows, int32_t moeInterSize, int32_t activationType)
281	{
282	    int64_t const element = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
283	    int64_t const numElements = static_cast<int64_t>(routedRows) * moeInterSize;
284	    if (element >= numElements)
285	    {
286	        return;
287	    }
288	
289	    int32_t const row = static_cast<int32_t>(element / moeInterSize);
290	    int32_t const intermediate = static_cast<int32_t>(element % moeInterSize);
291	    float result{};
292	    if (activationType == kACT_SWIGLU)
293	    {
294	        int32_t const chunk = intermediate / kSWIGLU_CHUNK_ROWS;
295	        int32_t const rowInChunk = intermediate % kSWIGLU_CHUNK_ROWS;
296	        int32_t const upColumn = chunk * kSWIGLU_STORAGE_ROWS + rowInChunk;
297	        int32_t const gateColumn = upColumn + kSWIGLU_CHUNK_ROWS;
298	        int32_t const fc1N = 2 * moeInterSize;
299	        float const up = __half2float(rawFc1[static_cast<int64_t>(row) * fc1N + upColumn]);
300	        float const gate = __half2float(rawFc1[static_cast<int64_t>(row) * fc1N + gateColumn]);
301	        result = up * gate / (1.0F + expf(-gate));
302	    }
303	    else
304	    {
305	        float const projection = __half2float(rawFc1[static_cast<int64_t>(row) * moeInterSize + intermediate]);
306	        float const positive = projection > 0.0F ? projection : 0.0F;
307	        result = positive * positive;
308	    }
309	    activatedFc1[element] = __float2half_rn(result);
310	}
311	
312	__global__ void scatterOutputKernel(__half const* routedOutput, int32_t const* expandedToSorted,
313	    float const* topkWeights, __half* output, int32_t numTokens, int32_t topK, int32_t hiddenSize)
314	{
315	    int64_t const element = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
316	    int64_t const numElements = static_cast<int64_t>(numTokens) * hiddenSize;
317	    if (element >= numElements)
318	    {
319	        return;
320	    }
321	
322	    int32_t const token = static_cast<int32_t>(element / hiddenSize);
323	    int32_t const hidden = static_cast<int32_t>(element % hiddenSize);
324	    float accumulator{0.0F};
325	    for (int32_t slot = 0; slot < topK; ++slot)
326	    {
327	        int32_t const expandedRow = token * topK + slot;
328	        int32_t const sortedRow = expandedToSorted[expandedRow];
329	        accumulator += topkWeights[expandedRow]
330	            * __half2float(routedOutput[static_cast<int64_t>(sortedRow) * hiddenSize + hidden]);
331	    }
332	    output[element] = __float2half_rn(accumulator);
333	}
