337	cudaError_t buildF16MoeRoutingAndGemmMetadata(F16MoeRoutingBuffers const& buffers, F16MoeGemmSetup const& fc1Setup,
338	    F16MoeGemmSetup const& fc2Setup, int32_t const* topkIds, int32_t numTokens, int32_t topK, int32_t numExperts,
339	    cudaStream_t stream) noexcept
340	{
341	    if (topkIds == nullptr || buffers.expertCounts == nullptr || buffers.expertOffsets == nullptr
342	        || buffers.expertWriteOffsets == nullptr || buffers.sortedToExpanded == nullptr
343	        || buffers.expandedToSorted == nullptr || !isValidGemmSetup(fc1Setup) || !isValidGemmSetup(fc2Setup)
344	        || numTokens <= 0 || topK <= 0 || topK > kMAX_TOP_K || numTokens > std::numeric_limits<int32_t>::max() / topK
345	        || numExperts <= 0 || numExperts > kTHREADS_PER_BLOCK)
346	    {
347	        return cudaErrorInvalidValue;
348	    }
349	
350	    if (numTokens <= kMAX_FUSED_ROUTING_TOKENS)
351	    {
352	        return launchFusedBuildRoutingAndGemmMetadata(
353	            buffers, fc1Setup, fc2Setup, topkIds, numTokens, topK, numExperts, stream);
354	    }
355	
356	    int32_t const routedRows = numTokens * topK;
357	    cudaError_t error
358	        = cudaMemsetAsync(buffers.expertCounts, 0, static_cast<size_t>(numExperts) * sizeof(int32_t), stream);
359	    if (error != cudaSuccess)
360	    {
361	        return error;
362	    }
363	    countRoutesKernel<<<gridSize(routedRows), kTHREADS_PER_BLOCK, 0, stream>>>(
364	        topkIds, buffers.expertCounts, routedRows, numExperts);
365	    error = cudaGetLastError();
366	    if (error != cudaSuccess)
367	    {
368	        return error;
369	    }
370	    buildOffsetsKernel<<<1, kTHREADS_PER_BLOCK, 0, stream>>>(
371	        buffers.expertCounts, buffers.expertOffsets, buffers.expertWriteOffsets, fc1Setup, fc2Setup, numExperts);
372	    error = cudaGetLastError();
373	    if (error != cudaSuccess)
374	    {
375	        return error;
376	    }
377	    scatterRouteMapKernel<<<gridSize(routedRows), kTHREADS_PER_BLOCK, 0, stream>>>(topkIds, buffers.expertWriteOffsets,
378	        buffers.sortedToExpanded, buffers.expandedToSorted, routedRows, numExperts);
379	    return cudaGetLastError();
380	}
381	
382	cudaError_t gatherF16MoeHiddenRows(void const* hiddenStates, void* gatheredInput, int32_t const* sortedToExpanded,
383	    int32_t routedRows, int32_t topK, int32_t hiddenSize, cudaStream_t stream) noexcept
384	{
385	    if (hiddenStates == nullptr || gatheredInput == nullptr || sortedToExpanded == nullptr || routedRows <= 0
386	        || topK <= 0 || hiddenSize <= 0 || hiddenSize % kHALF_PER_VECTOR != 0)
387	    {
388	        return cudaErrorInvalidValue;
389	    }
390	    int32_t const vectorsPerRow = hiddenSize / kHALF_PER_VECTOR;
391	    int64_t const numVectors = static_cast<int64_t>(routedRows) * vectorsPerRow;
392	    gatherHiddenKernel<<<gridSize(numVectors), kTHREADS_PER_BLOCK, 0, stream>>>(static_cast<uint4 const*>(hiddenStates),
393	        static_cast<uint4*>(gatheredInput), sortedToExpanded, routedRows, topK, vectorsPerRow);
394	    return cudaGetLastError();
395	}
396	
397	cudaError_t activateF16Moe(void const* rawFc1, void* activatedFc1, int32_t routedRows, int32_t moeInterSize,
398	    int32_t activationType, cudaStream_t stream) noexcept
399	{
400	    if (rawFc1 == nullptr || activatedFc1 == nullptr || routedRows <= 0 || moeInterSize <= 0
401	        || (activationType != kACT_SWIGLU && activationType != kACT_RELU2))
402	    {
403	        return cudaErrorInvalidValue;
404	    }
405	    int64_t const numElements = static_cast<int64_t>(routedRows) * moeInterSize;
406	    activateFc1Kernel<<<gridSize(numElements), kTHREADS_PER_BLOCK, 0, stream>>>(static_cast<__half const*>(rawFc1),
407	        static_cast<__half*>(activatedFc1), routedRows, moeInterSize, activationType);
408	    return cudaGetLastError();
409	}
410	
411	cudaError_t scatterF16MoeOutput(void const* routedOutput, int32_t const* expandedToSorted, float const* topkWeights,
412	    void* output, int32_t numTokens, int32_t topK, int32_t hiddenSize, cudaStream_t stream) noexcept
413	{
414	    if (routedOutput == nullptr || expandedToSorted == nullptr || topkWeights == nullptr || output == nullptr
415	        || numTokens <= 0 || topK <= 0 || hiddenSize <= 0)
416	    {
417	        return cudaErrorInvalidValue;
418	    }
419	    int64_t const numElements = static_cast<int64_t>(numTokens) * hiddenSize;
420	    scatterOutputKernel<<<gridSize(numElements), kTHREADS_PER_BLOCK, 0, stream>>>(
421	        static_cast<__half const*>(routedOutput), expandedToSorted, topkWeights, static_cast<__half*>(output),
422	        numTokens, topK, hiddenSize);
423	    return cudaGetLastError();
424	}
